import { describe, it, expect } from "vitest";
import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx scoring", () => {
  // No Sphinx in the army — only Sphinx cards produce points
  it.todo("scores an empty army as 0");
  it.todo("scores an army with no Sphinx as 0 — [hydra, zombie] is 0");

  // Single Sphinx, type count at or below three → 1 point per type
  it.todo("scores a lone Sphinx as 1 — 1 type, not beyond three, 1 per type");
  it.todo("scores [sphinx, hydra] as 2 — 2 types at 1 per type");
  it.todo("scores [sphinx, hydra, zombie] as 3 — 3 types at 1 per type");

  // Single Sphinx, type count beyond three → 2 points per type
  it.todo("scores [sphinx, hydra, zombie, cyclops] as 8 — 4 types at 2 per type");
  it.todo("scores [sphinx, hydra, zombie, cyclops, orthrus] as 10 — 5 types at 2 per type");

  // Duplicate cards collapse to a single type
  it.todo("counts repeated monsters once — [sphinx, hydra, hydra] is 2");

  // Undead Warrior ranks are distinct types
  it.todo("counts one Undead Warrior rank as one type — [sphinx, undead-warrior(2), hydra] is 3");
  it.todo("counts two Undead Warrior ranks as two types — [sphinx, undead-warrior(1), undead-warrior(2)] is 3");
  it.todo("counts three Undead Warrior ranks as three types — [sphinx, undead-warrior(1), undead-warrior(2), undead-warrior(3)] is 8");
  it.todo("counts repeated Undead Warriors of the same rank once — [sphinx, undead-warrior(2), undead-warrior(2)] is 2");

  // Multiple Sphinx cards each score
  it.todo("scores each Sphinx card — [sphinx, sphinx] is 2");
  it.todo("scores each Sphinx card beyond three types — [sphinx, sphinx, hydra, zombie, cyclops] is 16");

  // Full-army combination
  it.todo("scores a full army of all seven monsters with all Undead Warrior ranks — 9 types at 2 per type is 18");
});

