export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

const countDistinctTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const THREE_TYPES = 3;
const POINTS_PER_TYPE_BEYOND_THREE = 2;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;
  const typeCount = countDistinctTypes(army);
  const isBeyondThreeTypes = typeCount > THREE_TYPES;
  return isBeyondThreeTypes
    ? typeCount * POINTS_PER_TYPE_BEYOND_THREE
    : typeCount;
};

