export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

const RANKLESS = "no-rank";

const typeOf = (card: Card): string =>
  `${card.monster}:${card.rank ?? RANKLESS}`;

const countDistinctTypes = (army: Card[]): number =>
  new Set(army.map(typeOf)).size;

const TYPE_BONUS_THRESHOLD = 3;
const POINTS_PER_TYPE = 1;
const POINTS_PER_TYPE_WITH_BONUS = 2;

const pointsPerType = (typeCount: number): number =>
  typeCount > TYPE_BONUS_THRESHOLD ? POINTS_PER_TYPE_WITH_BONUS : POINTS_PER_TYPE;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;
  const typeCount = countDistinctTypes(army);
  return typeCount * pointsPerType(typeCount);
};

